class Model(torch.nn.Module):
    def __init__(self, input_dim, cat_dim, is_complex):
        super(Model, self).__init__()
        self.input_dim = input_dim
        self.cat_dim = cat_dim
        self.is_complex = is_complex

    def forward(self, x):
        if self.is_complex:
