import torch
import torch.nn as nn


class Model(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_modules):
        super().__init__()
        self.module_dict = nn.ModuleDict(
            {f"module_{i}": nn.Conv2d(in_channels, out_channels, kernel_size) for i in range(num_modules)}
        )
        self.reference_tensor = torch.randint(0, out_channels, (1, out_channels, 1, 1))

    def forward(self, x):
        results = []
        for _, module in self.module_dict.items():
            results.append(module(x))
        concatenated = torch.cat(results, dim=0)
        isin_mask = torch.isin(concatenated, self.reference_tensor.to(concatenated.device))
        return concatenated, isin_mask


