class Model(nn.Module):
    def __init__(self, module_dict_size, num_channels):
        super().__init__()
        # Create a module dictionary with specified size
        self.module_dict = nn.ModuleDict(
            {
                f"module_{i}": nn.Sequential(
                    nn.Conv2d(num_channels, num_channels, kernel_size=3, padding=1),
                    nn.ReLU(),
                    nn.MaxPool2d(kernel_size=2, stride=2),
                )
                for i in range(module_dict_size)
            }
        )

    def forward(self, x):
        # Apply each module in the dictionary
        for module in self.module_dict.values():
            x = module(x)
        # Use torch.argmax to get indices of maximum values along specific dimensions
        max_indices = torch.argmax(x, dim=1)
        return max_indices


