class Model(nn.Module):
    def __init__(self, parameter_list_size, num_layers, input_dim, output_dim):
        super(Model, self).__init__()
        self.parameter_list = nn.ParameterList(
            [nn.Parameter(torch.randn(input_dim, output_dim)) for _ in range(num_layers)]
        )
        self.softplus = nn.Softplus()
        self.parameter_list_size = parameter_list_size

