import torch
import torch.nn as nn


class InstanceNormalization(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.scale = nn.Parameter(torch.Tensor(num_features).uniform_())
        self.bias = nn.Parameter(torch.Tensor(num_features).uniform_())
        self.eps = eps

    def forward(self, x: torch.Tensor):
        mean = torch.mean(x, dim=[2, 3], keepdim=True)
        var = torch.mean((x - mean) ** 2, dim=[2, 3], keepdim=True)
        x = (x - mean) * torch.rsqrt(var + self.eps)
        x = x * self.scale[None, :, None, None] + self.bias[None, :, None, None]
        return x


class BatchNormalization(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5, momentum: float = 0.1):
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        self.momentum = momentum
        self.gamma = nn.Parameter(torch.Tensor(num_features).uniform_())
        self.beta = nn.Parameter(torch.Tensor(num_features).uniform_())
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))

    def forward(self, x: torch.Tensor):
        if self.training:
            mean = torch.mean(x, dim=[0, 2, 3], keepdim=True)
            var = torch.mean((x - mean) ** 2, dim=[0, 2, 3], keepdim=True)
            x = (x - mean) * torch.rsqrt(var + self.eps)
            mean = torch.mean(x, dim=[0, 2, 3], keepdim=True)
            var = torch.mean((x - mean) ** 2, dim=[0, 2, 3], keepdim=True)
            self.running_mean.mul_(1 - self.momentum).add_(mean.squeeze())
            self.running_var.mul_(1 - self.momentum).add_(var.squeeze())
        else:
            x = (x - self.running_mean[None, :, None, None]) * torch.rsqrt(
                self.running_var[None, :, None, None] + self.eps
            )
        x = x * self.gamma[None, :, None, None] + self.beta[None, :, None, None]
        return x


class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self.instance_norm = InstanceNormalization(num_features=3)
        self.batch_norm = BatchNormalization(num_features=3)

    def forward(self, x: torch.Tensor):
        x = self.instance_norm(x)
        x = self.batch_norm(x)
        return x


