        else:
            self.act = torch.nn.Identity()

        if use_dig:
            self.dig = torch.nn.Identity()
        else:
            self.dig = torch.nn.Identity()

    def forward(self, x):
        x = self.conv(x)
        x = self.act(x)
        x = self.dig(x)
        return x


