class Model(torch.nn.Module):
    def __init__(self, size: int, diagonal: int = 0):
        super().__init__()
        self.size = size
        self.diagonal = diagonal

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        triu_mask = torch.triu(
            torch.ones((self.size, self.size), dtype=x.dtype, device=x.device), diagonal=self.diagonal
